import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Color } = ctx.THREE;

  // Create root container
  const root = new Group();

  // 1. DESIGN TOKENS & STAGE BACKGROUND
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Build local backdrop plane (~7x6 units at z=-2.5) carrying gradients
  const bgGeom = new PlaneGeometry(7.5, 6.5);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.color.set(colors.surface);
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // 2. HERO SUBJECT - TEXTURED PLANE
  // Primary interaction card dimension
  const cardWidth = 3.2;
  const cardHeight = 2.0;
  const cardGeom = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });
  cardMat.color.set('#ffffff'); // Keep high-albedo baseline, let texture provide detail

  const cardMesh = new Mesh(cardGeom, cardMat);
  cardMesh.position.set(0, 0, 0);
  root.add(cardMesh);

  // Async texture load
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      cardMat.map = texture;
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load image for journal card:', err);
    });
  }

  // 3. SEAMLESS INTERACTION & DATA BINDINGS
  const hoverColor = new Color(colors.accent);
  const baseColor = new Color('#ffffff');

  // Ground contact shadow to ground the physical card
  const shadowGeom = new PlaneGeometry(cardWidth * 1.15, 0.2);
  const shadowMat = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.45
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -(cardHeight / 2) - 0.08, -0.05);
  root.add(shadowMesh);

  // Interactive callbacks
  let isHovered = false;
  const tl = gsap.timeline();

  const handlePointerOver = () => {
    if (isHovered) return;
    isHovered = true;
    gsap.killTweensOf([cardMesh.position, cardMesh.scale, shadowMesh.position, shadowMesh.scale]);

    // Weighted-settle style rise-in (subtle 0.15 scene units)
    gsap.to(cardMesh.position, {
      y: 0.15,
      z: 0.1,
      duration: 0.5,
      ease: 'power3.out'
    });
    gsap.to(shadowMesh.position, {
      y: -(cardHeight / 2) - 0.18,
      duration: 0.5,
      ease: 'power3.out'
    });
    gsap.to(shadowMesh.scale, {
      x: 1.05,
      y: 0.85,
      duration: 0.5,
      ease: 'power3.out'
    });
  };

  const handlePointerOut = () => {
    if (!isHovered) return;
    isHovered = false;
    gsap.killTweensOf([cardMesh.position, cardMesh.scale, shadowMesh.position, shadowMesh.scale]);

    // Return to resting profile
    gsap.to(cardMesh.position, {
      y: 0,
      z: 0,
      duration: 0.7,
      ease: 'power4.out'
    });
    gsap.to(shadowMesh.position, {
      y: -(cardHeight / 2) - 0.08,
      duration: 0.7,
      ease: 'power4.out'
    });
    gsap.to(shadowMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.7,
      ease: 'power4.out'
    });
  };

  const handlePointerDown = () => {
    gsap.killTweensOf(cardMesh.scale);
    // Press scale 0.97 in 120ms
    gsap.to(cardMesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out(2)'
    });
  };

  const handlePointerUp = () => {
    gsap.killTweensOf(cardMesh.scale);
    gsap.to(cardMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.4,
      ease: 'power2.out'
    });

    // Emit navigation/select action
    ctx.emit('hub-journal.select', { id: config.id ?? 'card-3' });
  };

  // Register Event Handlers conforming to the runtime surface requirements
  root.userData.handlers = {
    pointerover: handlePointerOver,
    pointerout: handlePointerOut,
    pointerdown: handlePointerDown,
    pointerup: handlePointerUp
  };

  // 4. CLEANUP INTERFACE
  root.userData.cleanup = () => {
    gsap.killTweensOf([cardMesh.position, cardMesh.scale, shadowMesh.position, shadowMesh.scale]);
    tl.kill();
    bgGeom.dispose();
    bgMat.dispose();
    cardGeom.dispose();
    cardMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
  };

  return root;
}
